<?php
if(session_status()===PHP_SESSION_NONE)session_start();
require_once __DIR__.'/../config/config.php';
require_once __DIR__.'/../includes/member_auth.php';
$memberId=(int)($_SESSION['member_id']??0);if($memberId<=0){header('Location: '.BASE_URL.'/login.php');exit;}
$stmt=$conn->prepare("SELECT id,church_id,crn,TRIM(CONCAT_WS(' ',first_name,middle_name,last_name)) full_name,dob,gender FROM members WHERE id=? AND is_archived=0 LIMIT 1");$stmt->bind_param('i',$memberId);$stmt->execute();$member=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$member){http_response_code(404);exit('Member not found.');}
$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['from']??''))?$_GET['from']:'';$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['to']??''))?$_GET['to']:'';$page=max(1,(int)($_GET['page']??1));$perPage=10;
$where=['record.member_id=?','record.church_id=?','record.status<>"voided"'];$types='ii';$params=[$memberId,$member['church_id']];if($from){$where[]='record.recorded_at>=?';$types.='s';$params[]=$from.' 00:00:00';}if($to){$where[]='record.recorded_at<?';$types.='s';$params[]=(new DateTimeImmutable($to))->modify('+1 day')->format('Y-m-d').' 00:00:00';}$whereSql=implode(' AND ',$where);
$baseSelect="SELECT record.id,record.recorded_at,record.encounter_type,record.follow_up_status,record.follow_up_date,record.referral_destination,record.notes,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=record.id AND observation_code='weight' LIMIT 1) weight,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=record.id AND observation_code='height' LIMIT 1) height,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=record.id AND observation_code='bmi' LIMIT 1) bmi,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=record.id AND observation_code='temperature' LIMIT 1) temperature,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=record.id AND observation_code='blood_pressure_systolic' LIMIT 1) systolic,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=record.id AND observation_code='blood_pressure_diastolic' LIMIT 1) diastolic,
 (SELECT value_numeric FROM health_observations WHERE health_record_id=record.id AND observation_code='blood_glucose' LIMIT 1) glucose,
 (SELECT measurement_context FROM health_observations WHERE health_record_id=record.id AND observation_code='blood_glucose' LIMIT 1) glucose_context,
 (SELECT result_code FROM health_screening_results WHERE health_record_id=record.id AND screening_code='malaria' LIMIT 1) malaria,
 (SELECT result_code FROM health_screening_results WHERE health_record_id=record.id AND screening_code='hepatitis_b' LIMIT 1) hepatitis_b
 FROM health_records record WHERE {$whereSql}";
if(($_GET['export']??'')==='csv'){
 $query=$conn->prepare($baseSelect.' ORDER BY record.recorded_at DESC,record.id DESC');$query->bind_param($types,...$params);$query->execute();$result=$query->get_result();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="health_history_'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Health history - '.$member['full_name'].' ('.$member['crn'].')']);fputcsv($out,['Filters','From: '.($from?:'All').' | To: '.($to?:'All')]);fputcsv($out,['Date','Encounter','Weight kg','Height cm','BMI','Temperature C','Blood pressure mmHg','Glucose mmol/L','Glucose context','Malaria','Hepatitis B','Follow-up','Notes']);while($row=$result->fetch_assoc())fputcsv($out,[$row['recorded_at'],$row['encounter_type'],$row['weight'],$row['height'],$row['bmi'],$row['temperature'],$row['systolic']!==null?$row['systolic'].'/'.$row['diastolic']:'',$row['glucose'],$row['glucose_context'],$row['malaria'],$row['hepatitis_b'],$row['follow_up_status'],$row['notes']]);fclose($out);exit;
}
$count=$conn->prepare('SELECT COUNT(*) total FROM health_records record WHERE '.$whereSql);$count->bind_param($types,...$params);$count->execute();$total=(int)$count->get_result()->fetch_assoc()['total'];$count->close();$totalPages=max(1,(int)ceil($total/$perPage));$page=min($page,$totalPages);$offset=($page-1)*$perPage;
$print=isset($_GET['print']);$limitSql=$print?'':' LIMIT ? OFFSET ?';$query=$conn->prepare($baseSelect.' ORDER BY record.recorded_at DESC,record.id DESC'.$limitSql);if($print){$query->bind_param($types,...$params);}else{$listTypes=$types.'ii';$listParams=array_merge($params,[$perPage,$offset]);$query->bind_param($listTypes,...$listParams);}$query->execute();$records=$query->get_result();$rows=[];while($row=$records->fetch_assoc())$rows[]=$row;$query->close();
$latest=$rows[0]??null;$page_title='My Health History';ob_start();
?>
<link rel="stylesheet" href="<?= BASE_URL ?>/assets/css/health-workspace.css">
<div class="container-fluid health-workspace py-3">
 <div class="health-hero mb-4 d-flex flex-wrap justify-content-between align-items-center"><div><h1><i class="fas fa-heartbeat mr-2"></i>My health history</h1><p><?= htmlspecialchars($member['full_name']) ?> · <?= htmlspecialchars($member['crn']) ?> · private member record</p></div><div class="no-print mt-2 mt-md-0"><a href="?<?= htmlspecialchars(http_build_query(array_filter(['from'=>$from,'to'=>$to,'export'=>'csv']))) ?>" class="btn btn-light"><i class="fas fa-file-csv mr-1"></i> CSV</a> <a target="_blank" rel="noopener" href="?<?= htmlspecialchars(http_build_query(array_filter(['from'=>$from,'to'=>$to,'print'=>1]))) ?>" class="btn btn-light"><i class="fas fa-print mr-1"></i> Print all</a></div></div>
 <div class="alert alert-info health-alert small"><i class="fas fa-info-circle mr-2"></i>This page presents recorded measurements and screening results. It does not provide a diagnosis. Contact a qualified health professional if you have concerns.</div>
 <form class="health-filter mb-4 no-print" method="get"><div class="form-row"><div class="form-group col-md-4"><label>From</label><input type="date" name="from" class="form-control" value="<?= htmlspecialchars($from) ?>"></div><div class="form-group col-md-4"><label>To</label><input type="date" name="to" class="form-control" value="<?= htmlspecialchars($to) ?>"></div><div class="form-group col-md-4 d-flex align-items-end"><button class="btn btn-health-primary mr-2">Apply filters</button><a class="btn btn-light" href="member_health_records.php">Clear</a></div></div></form>
 <?php if($latest):?><div class="health-kpis mb-4"><div class="health-kpi"><div class="health-kpi-value"><?= $latest['systolic']!==null?(int)$latest['systolic'].'/'.(int)$latest['diastolic']:'—' ?></div><div class="health-kpi-label">Latest blood pressure</div></div><div class="health-kpi"><div class="health-kpi-value"><?= $latest['weight']!==null?number_format((float)$latest['weight'],1):'—' ?></div><div class="health-kpi-label">Latest weight (kg)</div></div><div class="health-kpi"><div class="health-kpi-value"><?= $latest['temperature']!==null?number_format((float)$latest['temperature'],1):'—' ?></div><div class="health-kpi-label">Latest temperature (°C)</div></div><div class="health-kpi"><div class="health-kpi-value"><?= number_format($total) ?></div><div class="health-kpi-label">Recorded encounters</div></div></div><?php endif;?>
 <div class="health-panel"><div class="health-panel-header"><div><h2 class="health-section-title">Encounter history</h2><p class="health-section-copy">Measurements are shown only when they were actually recorded. BMI is never estimated without height.</p></div></div>
 <?php if(!$rows):?><div class="health-empty"><i class="fas fa-notes-medical fa-2x mb-2"></i><div>No health encounters match this period.</div></div><?php endif;?>
 <?php foreach($rows as $row):?><article class="health-panel-body border-bottom"><div class="d-flex flex-wrap justify-content-between mb-3"><div><div class="font-weight-bold"><?= date('d M Y, g:i A',strtotime($row['recorded_at'])) ?></div><small class="text-muted"><?= htmlspecialchars(ucfirst(str_replace('_',' ',$row['encounter_type']))) ?></small></div><span class="status-pill"><?= htmlspecialchars(ucfirst($row['follow_up_status'])) ?> follow-up</span></div><div class="metric-grid">
  <?php $metrics=[['Weight',$row['weight'],'kg'],['Height',$row['height'],'cm'],['BMI',$row['bmi'],'kg/m²'],['Temperature',$row['temperature'],'°C'],['Blood pressure',$row['systolic']!==null?$row['systolic'].'/'.$row['diastolic']:null,'mmHg'],['Blood glucose',$row['glucose'],'mmol/L']];foreach($metrics as [$label,$value,$unit]):if($value===null||$value==='')continue;?><div class="metric-card"><div class="metric-label"><?= $label ?></div><div class="h5 mb-0"><?= htmlspecialchars(is_numeric($value)?rtrim(rtrim(number_format((float)$value,1,'.',''),'0'),'.'):$value) ?> <small class="text-muted"><?= $unit ?></small></div><?php if($label==='Blood glucose'&&$row['glucose_context']):?><small class="text-muted"><?= htmlspecialchars(ucfirst(str_replace('_',' ',$row['glucose_context']))) ?></small><?php endif;?></div><?php endforeach;?>
 </div><?php if($row['malaria']||$row['hepatitis_b']):?><div class="mt-3"><span class="mr-3">Malaria: <span class="status-pill <?= htmlspecialchars($row['malaria']??'') ?>"><?= htmlspecialchars(ucfirst($row['malaria']??'Not recorded')) ?></span></span><span>Hepatitis B: <span class="status-pill <?= htmlspecialchars($row['hepatitis_b']??'') ?>"><?= htmlspecialchars(ucfirst($row['hepatitis_b']??'Not recorded')) ?></span></span></div><?php endif;?><?php if($row['notes']):?><div class="small text-muted mt-3"><strong>Notes:</strong> <?= nl2br(htmlspecialchars($row['notes'])) ?></div><?php endif;?><?php if($row['follow_up_date']):?><div class="alert alert-warning health-alert small mt-3 mb-0">Follow-up date: <?= date('d M Y',strtotime($row['follow_up_date'])) ?><?= $row['referral_destination']?' · '.$row['referral_destination']:'' ?></div><?php endif;?></article><?php endforeach;?>
 <?php if(!$print&&$totalPages>1):?><div class="health-panel-body d-flex justify-content-between no-print"><small>Showing <?= $offset+1 ?>–<?= min($offset+$perPage,$total) ?> of <?= $total ?></small><nav><ul class="pagination pagination-sm mb-0"><?php for($p=max(1,$page-2);$p<=min($totalPages,$page+2);$p++):?><li class="page-item <?= $p===$page?'active':'' ?>"><a class="page-link" href="?<?= htmlspecialchars(http_build_query(array_filter(['from'=>$from,'to'=>$to,'page'=>$p]))) ?>"><?= $p ?></a></li><?php endfor;?></ul></nav></div><?php endif;?></div>
</div>
